mapper.select:
select system_dept.id, system_dept.name, system_dept.code, system_dept.parent_id, system_dept.sort, system_dept.leader_user_id, system_dept.phone, system_dept.email, su.nickname as leaderUserName, system_dept.status from system_dept left join system_users su on su.id = system_dept.leader_user_id where system_dept.deleted = 0
and system_dept.name like #{name}
and system_dept.status = #{status}
order by system_dept.sort asc
